#include "split_if.hpp"
#include <cstddef>
#include <vector>
#include "keywords.hpp"
#include "tokens.hpp"

using blitz::tools::kind;
using blitz::tools::token;

namespace {
	// A line of the source: its tokens without the line break, and the line break.
	struct raw_line {
		std::vector<token> tokens;
		std::string        newline;
	};

	// A token that is not white space or a comment, and what it is.
	struct sig {
		size_t      at; // In raw_line::tokens
		std::string lower;
		bool        separator = false; // A : between statements (not the one of x:Int32)
	};

	std::vector<raw_line> split_raw(std::string const& source)
	{
		std::vector<raw_line> lines(1);
		for (auto& t : blitz::tools::tokenize(source)) {
			if (t.is(kind::newline)) {
				lines.back().newline = t.text;
				lines.emplace_back();
			} else {
				lines.back().tokens.push_back(std::move(t));
			}
		}
		return lines;
	}

	std::vector<sig> significant(raw_line const& line)
	{
		std::vector<sig> out;
		auto const&      t = line.tokens;
		for (size_t i = 0; i < t.size(); i++) {
			if (t[i].is(kind::space) || t[i].is(kind::comment)) {
				continue;
			}
			sig s{ i, blitz::tools::lower(t[i].text) };
			if (t[i].is(kind::separator)) {
				// x:Int32 has a : that touches a name and a type name, which is no separator.
				bool type_colon = (i > 0) && (i + 1 < t.size()) && t[i - 1].is(kind::word) && t[i + 1].is(kind::word) && blitz::tools::is_type_name(t[i + 1].text);
				s.separator     = !type_colon;
			}
			out.push_back(std::move(s));
		}
		return out;
	}

	bool is_word(raw_line const& line, sig const& s, const char* lower)
	{
		return line.tokens[s.at].is(kind::word) && (s.lower == lower);
	}

	bool is_keyword(raw_line const& line, sig const& s)
	{
		auto const& text = line.tokens[s.at].text;
		char        last = text.empty() ? 0 : text.back();
		return line.tokens[s.at].is(kind::word) && (last != '%') && (last != '#') && (last != '$') && !blitz::tools::keyword_spelling(text).empty();
	}

	// Where the Then of the If at 'at' is (at the top level of parentheses), or 0 if it has none.
	size_t find_then(raw_line const& line, std::vector<sig> const& s, size_t at)
	{
		int depth = 0;
		for (size_t i = at + 1; i < s.size(); i++) {
			auto const& t = line.tokens[s[i].at];
			depth += t.is_symbol("(") ? 1 : (t.is_symbol(")") ? -1 : 0);
			if (s[i].separator && (depth <= 0)) {
				return 0;
			}
			if ((depth == 0) && is_word(line, s[i], "then")) {
				return i;
			}
		}
		return 0;
	}

	// A call statement Name(...) whose ) is right in front of an Else, with no or more than one argument: the original reads the
	// parentheses as an expression there and rejects the line.
	bool rejected_call(raw_line const& line, std::vector<sig> const& s)
	{
		bool start = true;
		for (size_t i = 0; i < s.size(); i++) {
			bool was_start = start;
			start          = s[i].separator || is_word(line, s[i], "then") || is_word(line, s[i], "else");
			if (!was_start || !line.tokens[s[i].at].is(kind::word) || is_keyword(line, s[i]) || (i + 1 >= s.size()) || !line.tokens[s[i + 1].at].is_symbol("(")) {
				continue;
			}
			int    depth = 0;
			size_t commas = 0, close = 0;
			for (size_t j = i + 1; j < s.size(); j++) {
				auto const& t = line.tokens[s[j].at];
				depth += t.is_symbol("(") ? 1 : (t.is_symbol(")") ? -1 : 0);
				if ((depth == 1) && t.is_symbol(",")) {
					commas++;
				}
				if (depth == 0) {
					close = j;
					break;
				}
			}
			if ((close == 0) || (close + 1 >= s.size()) || !is_word(line, s[close + 1], "else")) {
				continue;
			}
			size_t arguments = (close == i + 2) ? 0 : commas + 1;
			if (arguments != 1) {
				return true;
			}
		}
		return false;
	}

	// The tokens from s[first] up to s[last] (exclusive), without white space at either end.
	raw_line piece(raw_line const& line, std::vector<sig> const& s, size_t first, size_t last)
	{
		raw_line out;
		if (first >= last) {
			return out;
		}
		size_t begin = s[first].at, end = s[last - 1].at + 1;
		out.tokens.assign(line.tokens.begin() + std::ptrdiff_t(begin), line.tokens.begin() + std::ptrdiff_t(end));
		return out;
	}

	// Splits the first one-line If of the line into an If block. Returns the lines that take its place, or nothing if it has none
	// (or one that can't be split safely).
	std::vector<raw_line> split(raw_line const& line, blitz::format::split_if mode)
	{
		auto s = significant(line);
		for (auto const& x : s) {
			// One-line If with ElseIf or a closing EndIf: rare, and left alone.
			if (is_word(line, x, "elseif") || is_word(line, x, "endif")) {
				return {};
			}
		}
		for (size_t i = 0; i + 1 < s.size(); i++) {
			if (is_word(line, s[i], "end") && is_word(line, s[i + 1], "if")) {
				return {};
			}
		}
		if ((mode == blitz::format::split_if::incompatible) && !rejected_call(line, s)) {
			return {};
		}

		// The first If that starts a statement.
		size_t at = s.size();
		bool   start = true;
		for (size_t i = 0; i < s.size(); i++) {
			if (start && is_word(line, s[i], "if")) {
				at = i;
				break;
			}
			start = s[i].separator;
		}
		if (at == s.size()) {
			return {};
		}
		size_t then = find_then(line, s, at);
		// No Then (the condition can't be told apart from the statements), or nothing behind it: a block If.
		if ((then == 0) || (then + 1 >= s.size()) || s[then + 1].separator) {
			return {};
		}

		// Its Else: the first one that no If behind the Then takes. An If behind the Then takes the first Else, and ends at the next.
		std::vector<bool> inner; // Whether each If inside has its Else.
		size_t            other = s.size();
		start                   = true;
		for (size_t i = then + 1; i < s.size(); i++) {
			bool was_start = start;
			start          = s[i].separator || is_word(line, s[i], "then") || is_word(line, s[i], "else");
			if (was_start && is_word(line, s[i], "if")) {
				size_t t = find_then(line, s, i);
				if ((t == 0) || (t + 1 >= s.size()) || s[t + 1].separator) {
					return {};
				}
				inner.push_back(false);
				i = t;
				continue;
			}
			if (is_word(line, s[i], "else")) {
				while (!inner.empty() && inner.back()) {
					inner.pop_back();
				}
				if (inner.empty()) {
					other = i;
					break;
				}
				inner.back() = true;
			}
		}

		std::vector<raw_line> out;
		// What is in front of the If stays on its line, without the : that ends it.
		if (at > 0) {
			out.push_back(piece(line, s, 0, at - 1));
		}
		auto head = piece(line, s, at, then + 1);
		// A comment stays on the line of the If.
		for (auto const& t : line.tokens) {
			if (t.is(kind::comment)) {
				head.tokens.push_back(token{ kind::space, " " });
				head.tokens.push_back(t);
			}
		}
		out.push_back(std::move(head));
		auto body = piece(line, s, then + 1, other);
		if (!body.tokens.empty()) {
			out.push_back(std::move(body));
		}
		if (other < s.size()) {
			out.push_back(piece(line, s, other, other + 1));
			auto alt = piece(line, s, other + 1, s.size());
			if (!alt.tokens.empty()) {
				out.push_back(std::move(alt));
			}
		}
		out.push_back(raw_line{ { token{ kind::word, "EndIf" } }, "" });
		return out;
	}
} // namespace

std::string blitz::format::split_one_line_ifs(std::string const& source, split_if mode)
{
	if (mode == split_if::never) {
		return source;
	}
	auto        lines = split_raw(source);
	std::string newline;
	for (auto const& l : lines) {
		if (!l.newline.empty()) {
			newline = l.newline;
			break;
		}
	}
	if (newline.empty()) {
		newline = "\n";
	}

	// The lines of a split If can hold one-line Ifs of their own (If a Then If b Then c Else d), which the loop reaches next.
	for (size_t n = 0; n < lines.size(); n++) {
		auto parts = split(lines[n], mode);
		if (parts.empty()) {
			continue;
		}
		std::string last_newline = lines[n].newline;
		for (auto& p : parts) {
			p.newline = newline;
		}
		parts.back().newline = last_newline.empty() ? (n + 1 < lines.size() ? newline : std::string()) : last_newline;
		lines.erase(lines.begin() + std::ptrdiff_t(n));
		lines.insert(lines.begin() + std::ptrdiff_t(n), parts.begin(), parts.end());
		n--; // The first part can be the statements in front of the If, or hold another If.
	}

	std::string out;
	for (auto const& l : lines) {
		for (auto const& t : l.tokens) {
			out += t.text;
		}
		out += l.newline;
	}
	return out;
}
